CREATE TABLE public.clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL CHECK (length(full_name) BETWEEN 2 AND 150), phone text NOT NULL CHECK (phone ~ '^\+[1-9][0-9]{7,14}$'), email text NOT NULL CHECK (length(email)<=255), residential_address text NOT NULL, company_name text NOT NULL, industry text NOT NULL, job_title text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', facebook text NOT NULL DEFAULT '', linkedin text NOT NULL DEFAULT '', social_other text NOT NULL DEFAULT '', membership_plans text[] NOT NULL CHECK (cardinality(membership_plans)>0 AND membership_plans <@ ARRAY['Daily','Weekly','Monthly','Dedicated Desk','Meeting room']::text[]), working_hours text[] NOT NULL CHECK (cardinality(working_hours)>0 AND working_hours <@ ARRAY['Morning','Afternoon','Evening','Flexible']::text[]), coworking_date date NOT NULL, special_requirements text NOT NULL DEFAULT '', emergency_name text NOT NULL, emergency_relationship text NOT NULL, emergency_phone text NOT NULL CHECK (emergency_phone ~ '^\+[1-9][0-9]{7,14}$'), comments text NOT NULL DEFAULT '', signature text NOT NULL, signature_date date NOT NULL, privacy_agreed boolean NOT NULL CHECK (privacy_agreed), signature_confirmed boolean NOT NULL CHECK (signature_confirmed), owner_id uuid, source text NOT NULL DEFAULT 'website' CHECK (source IN ('website','admin')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.clients TO authenticated;
GRANT ALL ON public.clients TO service_role;
ALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Administrators manage clients" ON public.clients FOR ALL TO authenticated USING (public.is_hr_admin(auth.uid())) WITH CHECK (public.is_hr_admin(auth.uid()));
CREATE INDEX clients_created_at_idx ON public.clients(created_at DESC);
CREATE TRIGGER clients_updated_at BEFORE UPDATE ON public.clients FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
ALTER TABLE public.profiles ADD COLUMN avatar_path text;
CREATE OR REPLACE FUNCTION public.protect_employee_fields() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.is_hr_admin(auth.uid()) AND (to_jsonb(NEW) - ARRAY['phone','address','city','country','emergency_contact_name','emergency_contact_phone','avatar_url','updated_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['phone','address','city','country','emergency_contact_name','emergency_contact_phone','avatar_url','updated_at']) THEN RAISE EXCEPTION 'Only an administrator may change employment details'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_employee_fields BEFORE UPDATE ON public.employees FOR EACH ROW EXECUTE FUNCTION public.protect_employee_fields();
REVOKE EXECUTE ON FUNCTION public.protect_employee_fields() FROM PUBLIC,anon,authenticated;